PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE cars (
  id          INTEGER PRIMARY KEY,
  year        TEXT,
  make        TEXT,
  model       TEXT,
  supername   TEXT,
  brand       TEXT,
  series      TEXT,
  country     TEXT,
  category    TEXT,
  description TEXT,
  broken_image INTEGER NOT NULL DEFAULT 0
, Cover INTEGER NOT NULL DEFAULT 0, name_format INTEGER NOT NULL DEFAULT 0);
CREATE TABLE makes (
  name      TEXT PRIMARY KEY,
  countries TEXT NOT NULL DEFAULT '[]'
);
CREATE TABLE coffee_stops (
  id           INTEGER PRIMARY KEY AUTOINCREMENT,
  name         TEXT NOT NULL,
  lat          REAL NOT NULL,
  lng          REAL NOT NULL,
  rating       INTEGER NOT NULL DEFAULT 0,
  notes        TEXT,
  date_visited TEXT,
  created_at   TEXT NOT NULL DEFAULT (datetime('now'))
, genre INTEGER NOT NULL DEFAULT 5, price INTEGER NOT NULL DEFAULT 5, location TEXT, visit_dates TEXT NOT NULL DEFAULT '[]', image_url TEXT, is_lunch INTEGER NOT NULL DEFAULT 0);
DELETE FROM sqlite_sequence;
