INSERT INTO "cars" ("id","year","make","model","supername","brand","series","country","category","description","broken_image","Cover","name_format") VALUES(548,'1975','Lotus','Esprit S1','','Hot Wheels','2015 HW Workshop: HW Garage','[]','["Retro Sports Cars"]','British supercar powered by the Lotus 970 4-cylinder engine. It''s probably most famous for the 1977 James Bond film The Spy Who Loved Me, where it was featured in a long chase sequence and was transformed into a submarine.',0,0,0);
INSERT INTO "cars" ("id","year","make","model","supername","brand","series","country","category","description","broken_image","Cover","name_format") VALUES(549,'1976','Lotus','Esprit V8','','Hot Wheels','2013 World Race 5-Pack','[]','["Retro Sports Cars"]','The name is Esprit...Lotus Esprit. Lightweight and super fast with a fiberglass body and a V8 engine, it''s no secret why this British beauty is the perfect spy car - originally made famous in a classic James Bond film. The Esprit goes from double zero to 60 in under 5 seconds.',0,0,0);
