INSERT INTO "cars" ("id","year","make","model","supername","brand","series","country","category","description","broken_image","Cover","name_format") VALUES(1299,'1992','Lancia','Delta HF Integrale Evoluzione','Didier Auriol''s','Mini GT','1992 Rally 1000 Lakes Winner #3','[]','["Retro Rally"]','At the end of the 1991 season, Lancia won their 5th consecutive World Rally Manufacturers Championship, and promptly celebrated by manufacturing a limited run of 400 special edition models, the ''Martini 5''.',0,0,0);
INSERT INTO "cars" ("id","year","make","model","supername","brand","series","country","category","description","broken_image","Cover","name_format") VALUES(1300,'1993','Toyota','Celica GT-Four ST185','','Pop Race','Safari Rally 1993 Winner #1','[]','["Retro Rally"]','It took great skill and ingenuity on the part of the designers and engineers tasked with developing the ST185 to come up with a machine capable of meeting all the performance and handling demands of international rallying. The finished product was named the "Carlos Sainz Edition" in honour of the achievements of the celebrated Spanish driver, who in 1990 had become Toyota''s first world rally champion.',0,0,0);
