INSERT INTO "cars" ("id","year","make","model","supername","brand","series","country","category","description","broken_image","Cover","name_format") VALUES(1808,'1965','Alfa Romeo','TZ2','','Kyosho','Alfa Romeo Minicar Collection 2','[]','[]','One of the most well-known sports models in the Alfa Romeo Giulia family, the TZ2 brings aesthetic and structural modifications to the previous model whilst preserving the line of the design (the body in particular, although this has been modified). In comparison with the first TZ, the TZ2 was modified to accommodate a lower set but more powerful engine with a reinforced fibreglass chassis and smaller tyres.',0,0,0);
