INSERT INTO "cars" ("id","year","make","model","supername","brand","series","country","category","description","broken_image","Cover","name_format") VALUES(2303,'1990','Nissan','Skyline GT-R (BNR32)','','Hot Wheels','2025 HW Screen Time','[]','[]','Punch the gas and crave the corners! Four-wheel drive, four-wheel-steering and 280 twin-turbocharged horsepower make this coupe a racing legend. After you roar past the other guys, they�ll admire the Skyline GT-R''s sculpted tail lights and big rear spoiler as it vanishes into the distance.',0,0,0);
