INSERT INTO "cars" ("id","year","make","model","supername","brand","series","country","category","description","broken_image","Cover","name_format") VALUES(2305,'1985','Proton','Saga','','Hot Wheels','2025 Factory Fresh','[]','[]','Drive around in the first national car of Malaysia. A celebration of automotive ingenuity, over 2 million units of the Saga have been built and sold globally, making it the best-selling car of PROTON.',0,0,0);
INSERT INTO "cars" ("id","year","make","model","supername","brand","series","country","category","description","broken_image","Cover","name_format") VALUES(2306,'1999','Honda','Civic Type R (EK9)','','Hot Wheels','2024 HW Speed Graphics (Silver Label)','[]','[]','Made exclusively for the Japanese Domestic Market, this 3-door hatchback came equipped with a 5-speed manual transmission, 182 hp 1.6L B16B DOHC VTEC engine and an interior that featured red bucket seats, titanium shift knob, leather wrapped steering wheel and red Type R badge. Truly one of the hottest hatches ever.',0,0,0);
