INSERT INTO "cars" ("id","year","make","model","supername","brand","series","country","category","description","broken_image","Cover","name_format") VALUES(2309,'1980','Land Rover','Range Rover Classic','','Hot Wheels','2024 HW Speed Graphics (Silver Label)','[]','[]','Originally launched as "A Car For All Reasons," the Range Rover is designed to perform equally well on or off the road. The RR twice won a grueling 6,200-mile race on a course that began in Paris, crossed the Sahara Desert, and finished in Western Africa.',0,0,0);
INSERT INTO "cars" ("id","year","make","model","supername","brand","series","country","category","description","broken_image","Cover","name_format") VALUES(2310,'2013','SRT','Viper','','Hot Wheels','2024 Stars & Stripes','[]','[]','With an even bigger sting than models before, the fifth generation Viper sports an 8.4L V10 and mega horsepower. It''s a venomous coupe, sure to leave the competition behind.',0,1,0);
INSERT INTO "cars" ("id","year","make","model","supername","brand","series","country","category","description","broken_image","Cover","name_format") VALUES(2311,'2013','Chevrolet','COPO Camaro','','Hot Wheels','2024 Stars & Stripes','[]','[]','This much-anticipated model features a twin-turbo, aluminum-block, direct injection V-6 engine and quite possibly more power than is stylishly possible.',0,0,0);
INSERT INTO "cars" ("id","year","make","model","supername","brand","series","country","category","description","broken_image","Cover","name_format") VALUES(2312,'2020','Ford','Shelby GT500','','Hot Wheels','2024 Stars & Stripes','[]','[]','A supercharged 5.2-liter V-8 cranking out 760-hp @ 7,300 rpm, and 7-speed dual clutch transmission work in concert to make this, "The most powerful street-legal Ford vehicle of all time."',0,0,0);
INSERT INTO "cars" ("id","year","make","model","supername","brand","series","country","category","description","broken_image","Cover","name_format") VALUES(2313,'1999','Ford','F-150 SVT Lightning','','Hot Wheels','2024 Fast & Furious Premium','[]','[]','Equipped with a 5.4L V-8 and a supercharger, the SVT Lightning had a top speed of 140 mph allowing it to claim and hold the title of, "The World''s Fastest Production Pickup Truck."',0,0,0);
