INSERT INTO "cars" ("id","year","make","model","supername","brand","series","country","category","description","broken_image","Cover","name_format") VALUES(2499,'2024','Peugeot','208','','Norev','Minijet Bianca White','[]','["City Commuters"]','This version of the new 208 in white with a black roof highlights the car''s evolution, both on the front (new radiator grille, new light signature including the 3 claws for the daytime running lights) and on the rear (new lights and new PEUGEOT branding on the strip between the rear lights).',0,0,0);
