INSERT INTO "cars" ("id","year","make","model","supername","brand","series","country","category","description","broken_image","Cover","name_format") VALUES(2501,'2025','Alpine','A290 GTS','','Norev','Minijet Alpine Vision Blue & Black','[]','["Hot Hatch"]','Norev proudly presents a 1:64 scale miniature of the brand-new Alpine A290 in its top-tier GTS trim, featuring exclusive wheels and decorative details. This model offers a faithful and playful representation of the Alpine original, perfect for collectors and admirers alike.',0,0,0);
